#include <omp.h>
#include <vector>

double productWithInverses(std::vector<double> const& x) {
    double result = 1.0;

    #pragma omp parallel for reduction(*:result)
    for (size_t i = 0; i < x.size(); ++i) {
        if (i % 2 == 0) {
            result *= x[i];
        } else {
            result *= 1.0 / x[i];
        }
    }

    return result;
}
